// ───────── ussd-handler/index.ts ─────────
import { serve } from 'https://deno.land/std@0.177.0/http/server.ts'

/**
 * A diagnostic endpoint. NOT the shop's USSD handler.
 *
 * The real flow is `super-service?action=ussd`: it looks the order up, reports
 * its delivery status, and can charge mobile money through NaloPay.
 *
 * WHAT THIS USED TO DO, AND WHY IT MATTERED
 * It logged the request — which is all it was ever for, while the USSD
 * integration was being worked out — and then answered:
 *
 *     Content-Type: text/plain
 *     Welcome to BEDTIME BEDDINGS & HOME
 *     1. Continue
 *     2. Exit
 *
 * Two problems, in a function that is deployed.
 *
 * 1. Neither option did anything. A customer choosing "1. Continue" reached a
 *    handler that cannot continue, because there is no session state here.
 * 2. The telco expects the JSON envelope the real handler returns
 *    ({ MSGTYPE, MSG, USSDMSG, continueSession }). Plain text is not that, so
 *    the session would break rather than show a menu.
 *
 * Nothing in this repository points a telco at this URL, so it is most likely
 * an unused leftover. "Most likely" is not a reason to leave a deployed
 * endpoint impersonating the shop's USSD menu: the telco's own configuration
 * is not visible from here, and if it ever did point here the failure would be
 * silent and would land on a paying customer.
 *
 * So it keeps the logging, answers in the protocol the telco actually speaks,
 * and says something a customer can act on. If this endpoint is reached, the
 * log says plainly that the wrong one was configured.
 */

const SHOP = 'BEDTIME BEDDINGS & HOME'
const SHOP_PHONE = Deno.env.get('SHOP_PHONE') || '054 812 4978'

serve(async (req) => {
  const url = new URL(req.url)
  const queryParams: Record<string, string> = {}
  for (const [k, v] of url.searchParams) queryParams[k] = v

  let body = ''
  try { body = await req.text() } catch { /* no body */ }

  // The diagnostic this function exists for.
  console.warn('ussd-handler was reached — this is NOT the real USSD handler.')
  console.warn('Point the telco at super-service?action=ussd instead.')
  console.log('METHOD:', req.method)
  console.log('QUERY:', JSON.stringify(queryParams))
  console.log('BODY:', body.slice(0, 2000))
  console.log('CONTENT-TYPE:', req.headers.get('content-type'))

  // The envelope the telco expects, ending the session rather than offering a
  // choice that cannot be honoured.
  const msg = `${SHOP}\nThis service is not available on this code.\nPlease call ${SHOP_PHONE}.`
  return new Response(JSON.stringify({
    MSGTYPE: false, MSG: msg, USSDMSG: msg, message: msg,
    reply: false, continueSession: false,
    note: 'diagnostic endpoint; the live handler is super-service?action=ussd',
  }), { status: 200, headers: { 'Content-Type': 'application/json' } })
})
